function UIActionPointDropRewardGroup:RefreshGroup(questId)
    self.questId = questId
    local _t = RewardConfMgr:GetInstance():GetTeamShowRewardData(questId)
    
    -- print(questId, table.dump(_t, nil, 3))
    local t = {}

    local __t = {}
    for k, v in pairs(_t) do
        if not t[checkString(v.type)] then
            t[checkString(v.type)] = {
                sortKey = checkNumber(v.type),
                data = {}
            }
            table.insert(__t, checkString(v.type))
        end

        table.insert(t[checkString(v.type)].data, v)
    end

    local isPass = QuestConfMgr:GetInstance():IsPassQuest(questId)
    if isPass then
        local data = __t[1]
        table.remove(__t, 1)
        table.insert(__t, data)
    end

    for i, v in ipairs(__t) do
        local data = t[checkString(v)]
        local go = self:GetRewardNode(i)

        local LT_Node = GetLuaBehaviour(go, DropRewardNodeLuaPath).Env
        LT_Node:RefreshNode(data.data, data.sortKey, i)
    end

    -- 把没在使用中的node关闭掉
    self:DeactiveNoUseRewardNode(#__t)
end

--- 获取一个node,不存在就创建一个
---@param index any
function UIActionPointDropRewardGroup:GetRewardNode(index)
    local goName = "GoodGroup"..tostring(index)
    local TF_Go = self.RT_RewardListRoot.transform:Find(goName)
    if isNotNull(TF_Go) then
        KTool.SetActive(TF_Go, true)
        return TF_Go.gameObject
    else
        local go = CfUtils.InstantiateGo(self.RT_RewardNode, self.RT_RewardListRoot)
        go.name = goName
        KTool.SetActive(TF_Go, true)
        return go
    end
end

--- 把没在使用中的node关闭掉
---@param inUseCount number 正在使用中的node数量
function UIActionPointDropRewardGroup:DeactiveNoUseRewardNode(inUseCount)
    inUseCount = math.max(1, inUseCount)
    local totalChildCount = self.RT_RewardListRoot.transform.childCount
    if totalChildCount > inUseCount then
        for i = inUseCount, totalChildCount, 1 do
            local unityIndex = i - 1
            local child = self.RT_RewardListRoot.transform:GetChild(unityIndex)
            KTool.SetActive(child, false)
        end
    end
end

return UIActionPointDropRewardGroup